import json
from pathlib import Path
p=Path(__file__).parent
sources={name:(p/(name+'.glsl')).read_text() for name in ('Common','BufferA','BufferB','BufferC','BufferD','Image')}
inline=json.dumps(sources,ensure_ascii=True).replace('</','<\\/')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Silk Waves — fullscreen</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#060711;color:#f0eef8;font:13px system-ui,-apple-system,sans-serif}main,.stage{position:fixed;inset:0}.stage canvas{display:block;width:100%;height:100%;cursor:default;touch-action:manipulation}#panel{position:fixed;z-index:3;right:12px;top:12px;max-width:calc(100vw - 24px);display:flex;align-items:flex-end;flex-direction:column;gap:8px}#panelTrigger{width:42px;height:42px;border:1px solid #ffffff40;border-radius:12px;background:#11192c9e;color:#fff;cursor:pointer;backdrop-filter:blur(15px);font-size:21px;opacity:0;pointer-events:none;transition:opacity .2s,background .18s}#panelContent{opacity:0;visibility:hidden;pointer-events:none;transform:translateY(-6px);transition:opacity .18s,transform .18s,visibility .18s;background:#0b1020e8;border:1px solid #ffffff30;border-radius:13px;box-shadow:0 12px 35px #0009;padding:16px;width:260px;backdrop-filter:blur(20px)}#panel:hover #panelContent,#panel:focus-within #panelContent,#panel.open #panelContent{opacity:1;visibility:visible;pointer-events:auto;transform:none}#panel:hover #panelTrigger,#panel:focus-within #panelTrigger,#panel.open #panelTrigger{opacity:1;pointer-events:auto;background:#243150d9}h1{font-size:17px;letter-spacing:-.3px;margin:0 0 14px}.field{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:11px 0}.field label,.small{color:#c2c9d8}.field select,.field button{border:1px solid #ffffff35;border-radius:7px;background:#202b44;color:#fff;padding:8px;cursor:pointer;max-width:150px}.field input{accent-color:#a9a5ff}.field button{max-width:none}#monthPicker{position:relative;width:150px;flex:0 0 150px}#monthPicker summary{display:flex;align-items:center;gap:8px;cursor:pointer;list-style:none;border:1px solid #ffffff35;border-radius:7px;background:#202b44;padding:8px;color:#fff;user-select:none}#monthPicker summary::-webkit-details-marker{display:none}#monthPicker summary:focus-visible,.month-option:focus-visible{outline:2px solid #b8c6ff;outline-offset:2px}#monthCurrent{white-space:nowrap;flex:1}#monthPicker .chevron{opacity:.7}.month-swatch{display:inline-block;width:18px;height:18px;border:1px solid #ffffff55;border-radius:50%;flex:none;box-shadow:0 0 0 1px #0002}.auto-swatch{background:conic-gradient(#dcdeed 0deg,#eab76c 70deg,#67a7e6 140deg,#b573c5 210deg,#d47c87 280deg,#dcdeed 360deg)}.month-menu{position:absolute;right:0;top:calc(100% + 5px);width:177px;max-height:min(420px,65vh);overflow-y:auto;background:#151f35;border:1px solid #ffffff40;border-radius:9px;padding:5px;box-shadow:0 15px 45px #000c;z-index:20}.month-option{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;border:0;background:transparent;color:#f7f7fd;text-align:left;border-radius:6px;cursor:pointer;font:inherit}.month-option:hover,.month-option[aria-selected="true"]{background:#344566}#monthPicker:not([open]) .month-menu{display:none}#auto[hidden]{display:none}.actions{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}#status{color:#bbc4d5;font-size:11px;line-height:1.5;overflow-wrap:anywhere}#hint{color:#bdc4d4;font-size:11px;line-height:1.4;margin-top:12px}#error{position:fixed;z-index:2;left:16px;bottom:16px;max-width:min(650px,calc(100vw - 32px));background:#180f18d9;color:#fff;border-radius:10px;padding:12px 15px;display:none}#error.visible{display:block}@media(hover:none){#panelTrigger{width:45px;height:45px}}
</style></head><body><main><div class="stage"><canvas id="screen" width="960" height="540" aria-label="Silk Waves animated background"></canvas></div><div id="error" role="alert"></div><aside id="panel" aria-label="Silk Waves controls"><button id="panelTrigger" aria-label="Show or hide controls" aria-expanded="false" aria-controls="panelContent" title="Settings">⚙</button><div id="panelContent"><h1>Silk Waves</h1><div class="field"><span class="small" id="monthLabel">Month</span><details id="monthPicker"><summary aria-labelledby="monthLabel monthCurrent"><span class="month-swatch" id="selectedSwatch" aria-hidden="true"></span><span id="monthCurrent">Automatic</span><span class="chevron" aria-hidden="true">▾</span></summary><div class="month-menu" role="listbox" aria-label="Month"><button type="button" class="month-option" data-month="auto" role="option" aria-selected="true"><span class="month-swatch auto-swatch" aria-hidden="true"></span>Automatic</button><button type="button" class="month-option" data-month="0" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#d9dce2,#a9aeb8)" aria-hidden="true"></span>January</button><button type="button" class="month-option" data-month="1" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#e8cf6a,#c29a1c)" aria-hidden="true"></span>February</button><button type="button" class="month-option" data-month="2" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#a6cf62,#5e9a2c)" aria-hidden="true"></span>March</button><button type="button" class="month-option" data-month="3" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#f0a8be,#d2668c)" aria-hidden="true"></span>April</button><button type="button" class="month-option" data-month="4" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#5fb874,#1f7a3a)" aria-hidden="true"></span>May</button><button type="button" class="month-option" data-month="5" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#be98e0,#7a52b8)" aria-hidden="true"></span>June</button><button type="button" class="month-option" data-month="6" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#48d2c4,#0f8c8c)" aria-hidden="true"></span>July</button><button type="button" class="month-option" data-month="7" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#4e9ae6,#1a3f9e)" aria-hidden="true"></span>August</button><button type="button" class="month-option" data-month="8" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#d47ae0,#8e2ca4)" aria-hidden="true"></span>September</button><button type="button" class="month-option" data-month="9" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#f2b94a,#c8780c)" aria-hidden="true"></span>October</button><button type="button" class="month-option" data-month="10" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#b98a55,#6e4a22)" aria-hidden="true"></span>November</button><button type="button" class="month-option" data-month="11" role="option" aria-selected="false"><span class="month-swatch" style="background:linear-gradient(180deg,#ee6a52,#a8261e)" aria-hidden="true"></span>December</button></div></details><select id="month" hidden aria-hidden="true"><option value="auto" selected>Automatic</option><option value="0">January</option><option value="1">February</option><option value="2">March</option><option value="3">April</option><option value="4">May</option><option value="5">June</option><option value="6">July</option><option value="7">August</option><option value="8">September</option><option value="9">October</option><option value="10">November</option><option value="11">December</option></select></div><div class="field"><label for="lighting">Lighting</label><select id="lighting" aria-label="Time of day"><option value="auto">Current time</option><option value="day">Day (noon)</option><option value="dusk">Dusk (6 PM)</option><option value="night">Night (midnight)</option></select></div><div class="field"><label for="resolution">Render quality</label><select id="resolution"><option value="540">540p · fast</option><option value="720">720p · HD</option><option value="1080">1080p · Full HD</option><option value="1440">1440p · QHD</option><option value="2160">2160p · up to 4K</option><option value="native">Native / Full resolution · display pixels</option></select></div><div class="field"><label for="frameRate">Frame rate</label><select id="frameRate"><option value="30">30 FPS · efficient</option><option value="60" selected>60 FPS · smooth</option><option value="uncapped">Uncapped · display/browser max</option></select></div><div class="field"><span class="small">Measured</span><strong id="fpsLabel">— FPS</strong></div><div class="field"><label for="pause">Pause animation</label><input id="pause" type="checkbox"></div><div class="actions"><button id="reset">Restart animation</button></div><div id="status">Starting renderer…</div><div id="hint">Starts with your current month and time. Choose a month using its color swatch, or try Day/Dusk/Night here. Move the pointer away to hide all settings; hover the top-right corner to bring them back. Native / Full resolution matches your display’s physical pixels, including displays above 4K. It may be demanding; 30 FPS or a lower resolution can reduce GPU load. Uncapped draws at every available browser animation frame, usually up to the display refresh rate.</div></div></aside></main><script>window.SILK_SOURCES=__SOURCES__;</script><script>__RUNNER__</script></body></html>'''
html=html.replace('__SOURCES__',inline).replace('__RUNNER__',(p/'runner.js').read_text().replace('</script','<\\/script'))
(p/'SilkWaves.html').write_text(html)
print('Created',p/'SilkWaves.html','size',len(html))
